#!/usr/bin/env bash
# The default-options test. features.yml runs only the scenarios
# (--skip-autogenerated): this feature has no default pins, so installing it
# with its defaults fails by design and this script is not reached there. It
# is kept for a local run that supplies a pin through the image (for example
# `devcontainer features test -f cli-opencode -i <image with CLI_OPENCODE_*
# ENV>`).
set -e

# shellcheck source=/dev/null
source dev-container-features-test-lib
# shellcheck source=opencode-checks.sh
source "$(dirname "$0")/opencode-checks.sh"

check "opencode resolves to /usr/local/bin/opencode" _opencode_is_local_bin
check "opencode is mode 0755, owned by root" _opencode_mode_owner
check "opencode --version runs" opencode --version

reportResults
